import{_ as s,o as a,c as t,a as e}from"./app.83c7065c.js";const h=JSON.parse('{"title":"Mac桌面端webview打开页面失败排查","description":"","frontmatter":{"title":"Mac桌面端webview打开页面失败排查","date":"2020-10-12"},"headers":[],"relativePath":"2020/mac-desktop-webview-debugging.md","lastUpdated":1786184870000}'),n={name:"2020/mac-desktop-webview-debugging.md"},l=e(`<h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-hidden="true">#</a></h3><p>公司产品的Mac桌面端使用webview打开公司PC端主页，主页上有多个Tab。<br> 其中一个Tab（以下简称<code>A Tab</code>，对应地址以下代称为：<code>https://correct.domain.com</code>）可以跳转到我负责的PC端页面（以下简称B页，对应地址<code>https://correct.domain.com/desktop</code>）。</p><h3 id="问题描述" tabindex="-1">问题描述 <a class="header-anchor" href="#问题描述" aria-hidden="true">#</a></h3><p>Mac开发同事反馈在Mac桌面端里点击<code>A Tab</code>无法成功跳转，变成了空白页面，而其他Tab都可以正常点击跳转。</p><h3 id="排查过程" tabindex="-1">排查过程 <a class="header-anchor" href="#排查过程" aria-hidden="true">#</a></h3><p>这个bug已知信息非常少，而且涉及到2个项目的代码，只有一步步排查了。</p><ol><li><p>查看bug是否可以复现<br> Mac客户端内点击<code>A Tab</code>，页面确实变成空白，并且可以稳定复现。</p></li><li><p>查看主页上的跳转链接是否正确<br> 浏览器inspect就可以直接看，链接正确。</p></li><li><p>打开charles抓包Mac请求<br> 点击<code>A Tab</code>看如何跳转，结果发现了2条有意思的记录：</p></li></ol><table><thead><tr><th style="text-align:left;">url</th><th style="text-align:center;">状态码</th></tr></thead><tbody><tr><td style="text-align:left;"><code>https</code>😕/correct.domain.com</td><td style="text-align:center;">302</td></tr><tr><td style="text-align:left;"><code>http</code>😕/correct.domain.com/desktop</td><td style="text-align:center;">301</td></tr></tbody></table><p>302跳转是预期中的，从业务主域名跳转对应的PC端主页，但不知为什么本来该出现的https变成了http。</p><p><strong>所以可以定位问题了，点击确实可以跳转，但是因为出现了http链接，所以被webview拦截了。</strong> 接下来只需要排查哪一步出现这个重定向就可以了。</p><blockquote><p>注：苹果推出了<a href="https://developer.apple.com/documentation/security/preventing_insecure_network_connections" target="_blank" rel="noreferrer">ATS</a>，非https请求都会被拦截</p></blockquote><ol start="4"><li>排查Nginx<br> Nginx里只有如下的配置可能会影响到地址，但它只是重写http为https协议而已，并没有重定向到<code>/desktop</code>的功能。</li></ol><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">rewrite</span><span style="color:#A6ACCD;">      </span><span style="color:#C3E88D;">^</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">.</span><span style="color:#FFCB6B;">*</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;">$ </span><span style="color:#C3E88D;">https://</span><span style="color:#A6ACCD;">$host</span><span style="color:#A6ACCD;font-style:italic;">$1</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">permanent</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span></code></pre></div><p>事实上在浏览器上如果同样点击A Tab，跳转过程会有如下3条记录：</p><table><thead><tr><th style="text-align:left;">url</th><th style="text-align:center;">状态码</th></tr></thead><tbody><tr><td style="text-align:left;"><code>https</code>😕/correct.domain.com</td><td style="text-align:center;">302</td></tr><tr><td style="text-align:left;"><code>http</code>😕/correct.domain.com/desktop</td><td style="text-align:center;">301</td></tr><tr><td style="text-align:left;"><code>https</code>😕/correct.domain.com/desktop</td><td style="text-align:center;">200</td></tr></tbody></table><p>普通浏览器没有ATS机制，所以第2条http地址是可以301跳转到对应的https地址的。</p><p>排除Nginx配置问题，只能是代码层面的问题了。</p><ol start="5"><li>排查代码<br> 先搜索后端代码，以<code>/desktop</code>为关键字，然后在PHP路由文件里找到下面这段代码，问题就在这一行了。</li></ol><div class="language-php"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki material-theme-palenight has-highlighted-lines"><code><span class="line"><span style="color:#89DDFF;">$</span><span style="color:#A6ACCD;">url </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">$this-&gt;</span><span style="color:#A6ACCD;">params</span><span style="color:#89DDFF;">[</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">domain</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">]</span><span style="color:#89DDFF;">.&#39;</span><span style="color:#C3E88D;">desktop</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">$</span><span style="color:#A6ACCD;">params </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">$this-&gt;</span><span style="color:#A6ACCD;">request</span><span style="color:#89DDFF;">-&gt;</span><span style="color:#82AAFF;">get</span><span style="color:#89DDFF;">();</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">if</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">(!</span><span style="color:#82AAFF;">empty</span><span style="color:#89DDFF;">($</span><span style="color:#A6ACCD;">params</span><span style="color:#89DDFF;">))</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span></span>
<span class="line highlighted"><span style="color:#A6ACCD;">    </span><span style="color:#89DDFF;">$</span><span style="color:#A6ACCD;">url </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">[</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">/desktop</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">];</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#89DDFF;font-style:italic;">foreach</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">($</span><span style="color:#A6ACCD;">params </span><span style="color:#89DDFF;">as</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">$</span><span style="color:#A6ACCD;">key </span><span style="color:#89DDFF;">=&gt;</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">$</span><span style="color:#A6ACCD;">val</span><span style="color:#89DDFF;">)</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#A6ACCD;">        </span><span style="color:#89DDFF;">$</span><span style="color:#A6ACCD;">url</span><span style="color:#89DDFF;">[$</span><span style="color:#A6ACCD;">key</span><span style="color:#89DDFF;">]</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">=</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">$</span><span style="color:#A6ACCD;">val</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#89DDFF;">}</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"><span style="color:#89DDFF;">$this-&gt;</span><span style="color:#82AAFF;">redirect</span><span style="color:#89DDFF;">($</span><span style="color:#A6ACCD;">url</span><span style="color:#89DDFF;">);</span></span>
<span class="line"></span></code></pre></div><ol start="6"><li>交给后端同事改了一下这段代码，确保是https跳转，重新发布，bug消失</li></ol><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-hidden="true">#</a></h3><p>后端路由代码疏忽，无意中返回了http地址。因为http地址在浏览器中表现正常，能够正常跳转，所以没发现这个bug。</p><p>总耗时：断断续续大约2小时</p>`,23),o=[l];function p(c,r,D,i,d,y){return a(),t("div",null,o)}const A=s(n,[["render",p]]);export{h as __pageData,A as default};
